const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const date=d=>new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Jakarta'}).format(new Date(d));
const time=d=>new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'}).format(new Date(d))+' WIB';
const today=()=>new Date().toISOString().slice(0,10);
let user=null,state=null,pub=null,admin=null,filter='all',activeLesson=0,lesson=null,jobDraft=null,docEdit=null,searchTerm='';
const nav=[['dashboard','home','Beranda Saya'],['catalog','layers','Katalog Program'],['learning','book','Pembelajaran Saya'],['workspace','briefcase','Modul Kerja Saya'],['events','calendar','Event & Jadwal Saya'],['feedback','check','Tugas & Feedback'],['documents','file','Dokumen Saya'],['policies','folder','Kebijakan Perusahaan'],['billing','wallet','Langganan & Pembayaran'],['profile','users','Bantuan & Profil'],['knowledge','book','Pengetahuan Perusahaan']];
const adminNav=[['admin','home','Ringkasan Bisnis'],['knowledge','book','Pengetahuan Perusahaan'],['policies','folder','Dokumen & Kebijakan'],['members','users','Member & Hak Akses'],['payments','wallet','Pesanan & Pembayaran'],['manage-events','calendar','Event & Pendaftaran'],['reviews','check','Review & Dukungan'],['team','briefcase','Tugas Tim'],['settings','shield','Status Sistem']];
const route=()=>location.hash.slice(1)||'home';
let chatOpen=false,chatDraft='',chatBusy=false,chatError='',chatOwner=null;
function chatWidget(){
 if(chatOwner!==user.id){chatOwner=user.id;chatOpen=false;chatDraft='';chatBusy=false;chatError=''}
 return `<div id="chat-widget" class="chat-widget"><section class="chat-widget-panel" id="chat-widget-panel" role="dialog" aria-modal="false" aria-labelledby="chat-widget-title" ${chatOpen?'':'hidden'}><header><span class="module-icon violet">${icon('spark')}</span><div><h2 id="chat-widget-title">Maxton AI</h2><small>${esc(user.company)}</small></div>${button('chat-close',icon('close'),'icon-button','aria-label="Tutup chat"')}</header><div class="chat-widget-status">Pengetahuan perusahaan ${badge(state.aiConfigured?'API siap':'API belum diatur',state.aiConfigured?'green':'amber')}</div><div id="chat-widget-history" class="chat-widget-history">${state.chat.length?state.chat.map(c=>`<div class="chat-question">${esc(c.question)}</div><div class="chat-answer"><span class="eyebrow cyan-text">MAXTON AI</span><p class="prose">${esc(c.answer)}</p><div class="chat-sources">${(c.sources||[]).map(s=>button('view-source',`[${s.number}] ${esc(s.title)} · v${esc(s.version)}`,'source-chip',`data-id="${esc(s.id)}"`)).join('')}</div></div>`).join(''):`<div class="chat-widget-welcome"><span class="ai-emblem">${icon('spark')}</span><h3>Halo, ${esc(user.name.split(' ')[0])}.</h3><p>Tanyakan kebijakan dan SOP dari dokumen perusahaan Anda.</p>${button('chat-example','Bagaimana prosedur pengajuan pelatihan?','secondary')}</div>`}${chatBusy?'<p role="status" class="lavender-text">Menyiapkan jawaban berdasarkan dokumen…</p>':''}</div><div class="chat-widget-bottom"><div class="form-error" role="alert">${esc(chatError)}</div><form data-form="chat-widget" class="chat-form"><label for="chat-widget-question" class="sr-only">Pertanyaan kebijakan perusahaan</label><textarea id="chat-widget-question" name="question" required maxlength="2000" rows="2" placeholder="Tanyakan kebijakan perusahaan…" ${chatBusy?'disabled':''}>${esc(chatDraft)}</textarea><button class="btn primary" type="submit" aria-label="Kirim chat" ${chatBusy?'disabled':''}>${icon('arrow')}</button></form><small class="chat-note">Dokumen rujukan dikirim ke penyedia AI saat bertanya. Periksa sumber jawaban.</small>${link('knowledge','Buka Pengetahuan Perusahaan '+icon('arrow'),'text-link')}</div></section><button class="chat-widget-launcher" data-action="chat-toggle" aria-label="${chatOpen?'Minimalkan':'Buka'} chat AI" aria-expanded="${chatOpen}" aria-controls="chat-widget-panel">${icon(chatOpen?'close':'spark')}<span>Chat AI</span></button></div>`;
}
function paintChat(focus=false){const dock=$('#chat-widget');if(!dock)return;dock.outerHTML=chatWidget();const history=$('#chat-widget-history');if(history)history.scrollTop=history.scrollHeight;if(focus)$('#chat-widget-question')?.focus()}
async function sendChat(question){
 if(chatBusy)return;const owner=user.id;chatBusy=true;chatDraft=question;chatError='';paintChat();
 try{const result=await api('ai',{question});if(user?.id!==owner)return;const fresh=await api('state');if(user?.id!==owner)return;state=fresh;if(!state.chat.some(c=>c.question===question&&c.answer===result.answer))state.chat.push({question,...result});chatDraft=''}
 catch(error){if(user?.id===owner)chatError=error.message}
 finally{if(user?.id===owner){chatBusy=false;paintChat(true)}}
}
const link=(page,label,cls='')=>`<a class="${cls}" href="#${page}">${label}</a>`;
const button=(action,label,cls='secondary',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const badge=(label,color='violet')=>`<span class="badge ${color}">${esc(label)}</span>`;
const empty=(title,description,action='')=>`<div class="empty">${icon('layers')}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const textarea=(label,name,value='',extra='')=>`<label class="field"><span>${label}</span><textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const select=(label,name,options,value='')=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const title=(eyebrow,h,sub='',action='')=>`<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${h}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
async function api(path,data){const res=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},...(data===undefined?{}:{body:JSON.stringify(data)})});const json=await res.json();if(!res.ok)throw new Error(json.error||'Permintaan gagal.');return json}
async function refresh(){state=await api('state');user=state.user;if(user.role==='admin')admin=await api('admin/state')}
const has=id=>state?.access.some(a=>a.module===id&&new Date(a.end)>new Date());
const progress=p=>Math.round((state?.progress.find(r=>r.module===p.id)?.done.length||0)/p.lessons.length*100);
const progressBar=n=>`<div class="progress"><i style="width:${n}%"></i></div>`;
function logo(){return `<a class="brand" href="#home"><span class="brand-mark">M<span>✦</span></span><span>MAXTON<small>HUMAN CAPITAL<br>LEARNING CENTRE</small></span></a>`}
function productCard(p){const owned=has(p.id),n=progress(p);return `<article class="module-card"><div class="card-top"><span class="module-icon ${p.color}">${icon(p.icon)}</span>${badge(owned?'Akses aktif':p.level,owned?'green':p.color)}</div><span class="eyebrow">${p.tag}</span><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="module-meta">${icon('book')} ${p.lessons.length} materi <span>·</span> Akses 12 bulan</div>${owned?`<div class="progress-label"><span>Progres ${n}%</span><span>${state.progress.find(r=>r.module===p.id)?.done.length||0}/${p.lessons.length}</span></div>${progressBar(n)}`:`<div class="price">${money(p.price)} <small>/ tahun · ilustrasi</small></div>`}${link(owned?'learn/'+p.id:'product/'+p.id,owned?'Lanjutkan belajar '+icon('arrow'):'Lihat program '+icon('arrow'),'btn '+(owned?'secondary':'ghost'))}</article>`}
function eventCard(e){const registered=state?.registrations.some(r=>r.eventId===e.id),can=has(e.module);return `<article class="event-card"><div class="event-top">${badge(e.format,'cyan')}<span>${date(e.date)}</span></div><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><div class="event-detail">${icon('clock')} ${time(e.date)} · ${e.duration} menit</div><div class="event-detail">${icon('users')} ${esc(e.mentor)}</div><div class="event-bottom">${registered?badge('Terdaftar','green'):badge(can?'Termasuk modul Anda':'Akses modul diperlukan',can?'violet':'muted')}${user?(registered?button('event-detail','Lihat sesi '+icon('arrow'),'secondary',`data-id="${e.id}"`):button('event-register','Daftar event','primary',`data-id="${e.id}" ${can?'':'disabled'}`)):link('login','Login untuk daftar','btn secondary')}</div></article>`}
function publicPage(){return `<header class="public-header"><div class="container public-nav">${logo()}<nav>${link('home','Beranda','active')}${link('programs','Program & Modul')}${link('agenda','Jadwal Event')}<a href="#home" data-action="about">Tentang Maxton</a></nav><div class="header-actions">${link(user?'dashboard':'login',user?'Portal saya':'Masuk','btn ghost')}${link(user?'dashboard':'register',user?'Buka dashboard '+icon('arrow'):'Daftar Membership '+icon('arrow'),'btn primary')}</div></div></header><main class="public-main"><section class="hero container"><div class="hero-label"><span class="status-dot"></span> BELAJAR DARI PRAKTISI. BERDAMPAK DI TEMPAT KERJA.</div><h1>Bangun kompetensi.<br>Wujudkan <span>Human Capital</span><br>yang berdampak.</h1><p>Ruang belajar dan alat kerja untuk praktisi HR yang ingin berkembang.<br>Pelajari ilmunya, praktikkan keterampilannya, hasilkan perubahan nyata.</p><div class="hero-actions">${link('programs','Eksplorasi Program '+icon('arrow'),'btn primary')}${link('agenda',icon('calendar')+' Workshop & Kelas Zoom','btn secondary')}</div><div class="hero-note">${icon('shield')} Akses 12 bulan <span>·</span> Pembelajaran praktis <span>·</span> Dokumen sesuai perusahaan Anda</div><div class="hero-orbit" aria-hidden="true"><i></i><i></i><i></i><span>✦</span></div></section><section class="container stats-public"><div>${icon('layers')}<strong>9 bidang HR</strong><span>Pilih kompetensi yang dibutuhkan</span></div><div>${icon('calendar')}<strong>12 bulan</strong><span>Belajar sesuai ritme Anda</span></div><div>${icon('file')}<strong>Belajar → praktik</strong><span>Materi, template & dokumen kerja</span></div><div>${icon('users')}<strong>Bersama praktisi</strong><span>Workshop, review & pendampingan</span></div></section><section class="container section" id="program-section"><div class="section-heading"><div><span class="eyebrow cyan-text">KURIKULUM UNTUK PEKERJAAN NYATA</span><h2>Kembangkan skill.<br>Perluas dampak Anda.</h2></div><p>Dari fondasi operasional hingga strategi Human Capital.<br>Pilih jalur yang paling relevan untuk Anda.</p></div><div class="chips" role="group" aria-label="Filter tingkat program">${['Semua','Fundamental','Intermediate','Advanced'].map((t,i)=>`<button class="chip ${filter===(i?'level:'+t:'all')?'selected':''}" data-action="public-filter" data-id="${i?'level:'+t:'all'}">${t}</button>`).join('')}</div><div class="module-grid">${pub.products.filter(p=>filter==='all'||p.level===filter.replace('level:','')).map(productCard).join('')}</div><div class="demo-note">Harga, materi, dan jadwal pada versi lokal ini adalah data ilustrasi untuk uji coba.</div></section><section class="container showcase"><div><span class="eyebrow cyan-text">LEBIH DARI SEKADAR MATERI</span><h2>Dari pengetahuan<br>menjadi <span class="lavender-text">dokumen nyata.</span></h2><p>Susun Job Description melalui lembar kerja terstruktur. Simpan konteks perusahaan Anda dan gunakan kebijakan internal sebagai sumber rujukan.</p><div class="feature-line">${icon('shield')} Dokumen privat sesuai hak akses</div><div class="feature-line">${icon('spark')} AI dengan sumber kebijakan perusahaan</div>${link(user?'workspace':'register','Mulai perjalanan Anda '+icon('arrow'),'btn primary')}</div><div class="preview-mini"><div class="mini-toolbar"><i></i><i></i><i></i><span>MAXTON · WORKSPACE</span></div><div class="preview-paper"><span class="eyebrow green-text">PT PERUSAHAAN ANDA</span><h3>Job Description</h3><div class="mini-line wide"></div><div class="mini-line"></div><div class="mini-line wide"></div><div class="mini-box">${icon('briefcase')} HR Supervisor ${badge('Draft','violet')}</div><h4>Tujuan Jabatan</h4><p>Menghubungkan kebutuhan organisasi dengan peran dan kontribusi yang jelas.</p>${progressBar(65)}<small>Disusun dengan konteks perusahaan Anda</small></div></div></section><section class="container section" id="event-section"><div class="section-heading"><div><span class="eyebrow cyan-text">BELAJAR, BERDISKUSI, BERTUMBUH</span><h2>Ruang bertemu para praktisi.</h2></div><p>Workshop & kelas Zoom mendatang<br>Seluruh jadwal dalam WIB.</p></div><div class="event-grid">${pub.events.slice(0,2).map(eventCard).join('')}</div></section><section class="container faq"><span class="eyebrow">PERTANYAAN ANDA</span><h2>Kenali cara belajarnya.</h2>${[['Berapa lama akses membership berlaku?','Akses berlaku 12 bulan sejak pembayaran diverifikasi. Perpanjangan menambah masa akses sesuai modul yang dibeli.'],['Apakah semua modul termasuk dalam satu pembelian?','Hak akses mengikuti modul yang dibeli. Anda dapat menambah modul sesuai kebutuhan.'],['Apakah dokumen perusahaan saya bersifat privat?','Dokumen terpisah per akun. Akun lain tidak otomatis mendapat akses walaupun nama perusahaan sama.'],['Bagaimana cara mengikuti workshop?','Login, aktifkan modul terkait, lalu daftar pada event yang tersedia. Link sesi ditampilkan jika sudah disiapkan admin.']].map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</section><section class="container bottom-cta"><div><span class="eyebrow cyan-text">LANGKAH BERIKUTNYA DIMULAI DI SINI</span><h2>Investasi pada kompetensi.<br>Untuk perjalanan karier Anda.</h2></div>${link(user?'dashboard':'register','Mulai bersama Maxton '+icon('arrow'),'btn primary')}</section></main><footer class="container">${logo()}<span>© ${new Date().getFullYear()} Maxton · Versi lokal dengan data ilustrasi</span></footer>`}
function authPage(register=false){return `<div class="auth-layout"><aside class="auth-story">${logo()}<div><span class="eyebrow cyan-text">YOUR NEXT CHAPTER STARTS HERE</span><h1>Pengetahuan yang<br>menggerakkan<br><span>perubahan.</span></h1><p>Belajar bersama praktisi. Kembangkan kompetensi.<br>Bawa dampaknya ke tempat kerja Anda.</p><div class="auth-symbol">✦</div></div><small>MAXTON HUMAN CAPITAL LEARNING CENTRE</small></aside><main class="auth-main"><div class="auth-card">${link('home','← Kembali ke website','back-link')}<span class="eyebrow">SELAMAT DATANG DI MAXTON</span><h1>${register?'Mulai perjalanan Anda.':'Senang bertemu kembali.'}</h1><p>${register?'Buat akun untuk memilih program dan mengembangkan kompetensi Anda.':'Masuk untuk melanjutkan pembelajaran dan pekerjaan Anda.'}</p><form data-form="${register?'register':'login'}">${register?field('Nama lengkap','name','','text','required autocomplete="name"')+field('Perusahaan','company','','text','required')+field('Jabatan','position'):''}${field('Email','email','','email','required autocomplete="email"')}${field('Password','password','','password',`required minlength="10" autocomplete="${register?'new-password':'current-password'}"`)}${register?'<label class="checkbox"><input type="checkbox" required> Saya memahami ini aplikasi lokal dengan data contoh.</label>':''}<div class="form-error" role="alert"></div><button class="btn primary full" type="submit">${register?'Buat akun':'Masuk ke dashboard'} ${icon('arrow')}</button></form><p class="auth-switch">${register?'Sudah punya akun? '+link('login','Masuk'):'Belum menjadi member? '+link('register','Daftar sekarang')}</p>${!register?`<div class="demo-login"><span class="eyebrow">AKUN UJI COBA LOKAL</span>${button('demo-member','Isi akun member','secondary')}${button('demo-admin','Isi akun admin','secondary')}<small>Login contoh hanya untuk pengembangan lokal.</small></div>`:''}</div></main></div>`}
function shell(content){const page=route().split('/')[0],isAdmin=user.role==='admin';return `<aside class="sidebar">${logo()}<div class="company-box"><span>WORKSPACE AKTIF</span><strong><i class="status-dot"></i>${esc(user.company)}</strong></div><nav>${(isAdmin?adminNav:nav).map(([id,i,label])=>link(id,icon(i)+`<span>${label}</span>`,page===id?'nav-link selected':'nav-link')).join('')}</nav><div class="sidebar-bottom"><div class="learning-note">${icon('shield')}<span>Workspace privat<small>Data perusahaan Anda terlindungi</small></span></div>${button('logout',icon('logout')+' Keluar','ghost full')}</div></aside><div class="app-shell"><header class="topbar">${button('menu',icon('menu'),'icon-button mobile-menu','aria-label="Buka navigasi"')}<div class="search-box">${icon('search')}<input id="global-search" placeholder="Cari program, modul, atau kebijakan…" aria-label="Cari program"><kbd>↵</kbd></div><span class="workspace-pill">${icon('briefcase')} ${esc(user.company)}</span><div class="topbar-right">${link(isAdmin?'reviews':'feedback',icon('bell'),'notification')}<div class="user-mini"><strong>${isAdmin?'Administrator':'Member Maxton'}</strong><small>${esc(user.name)}</small></div><span class="avatar">${esc(user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span></div></header><main class="workspace-content">${content}<div class="workspace-footer"><span>MAXTON HUMAN CAPITAL LEARNING CENTRE</span><span><i class="status-dot"></i> Lokal · Data ilustrasi</span></div></main></div>${chatWidget()}`}
function dashboard(){const jd=state.products[0],p=progress(jd),active=state.access.filter(a=>new Date(a.end)>new Date()),next=state.events.find(e=>state.registrations.some(r=>r.eventId===e.id));return `${title('YOUR LEARNING WORKSPACE',`Selamat datang kembali,<br>${esc(user.name.split(' ')[0])}.`,'Satu langkah belajar hari ini. Dampak yang lebih besar esok hari.',badge('Member aktif','green'))}<section class="focus-card"><div><div class="focus-tag">${badge('Fokus pembelajaran','violet')}<span>MODUL 01</span></div><h2>${has('jd')?'Penyusunan Job Description<br>yang berdampak.':'Temukan jalur belajar<br>yang tepat untuk Anda.'}</h2><p>Bangun kejelasan peran, tanggung jawab, dan kontribusi<br>yang selaras dengan kebutuhan perusahaan.</p>${has('jd')?`<div class="progress-label"><span>${p}% selesai</span><span>${state.progress.find(r=>r.module==='jd')?.done.length||0} dari 4 materi</span></div>${progressBar(p)}`:''}</div><div class="focus-actions">${link(has('jd')?'learn/jd':'catalog',icon('play')+(has('jd')?'Lanjutkan belajar':'Jelajahi program'),'btn primary')}${has('jd')?link('workspace',icon('file')+' Buka lembar kerja','btn secondary'):''}<span>Belajar. Praktikkan. Berkembang.</span></div><span class="focus-decoration" aria-hidden="true">✦</span></section><div class="metric-grid">${[[active.length,'Modul aktif','Akses sesuai kebutuhan','book','violet'],[state.jobs.length,'Dokumen kerja','Draft yang tersimpan','file','green'],[state.registrations.length,'Event terdaftar','Ruang belajar bersama','calendar','cyan'],[state.submissions.filter(s=>s.status==='Menunggu review').length,'Menunggu review','Feedback dari praktisi','chat','peach']].map(([n,t,s,i,c])=>`<div class="metric"><div>${t}<span class="module-icon ${c}">${icon(i)}</span></div><strong>${n}<small>${t==='Modul aktif'?'/ 9 program':''}</small></strong><p>${s}</p></div>`).join('')}</div><div class="section-heading compact"><div><span class="eyebrow">LEARNING PATH</span><h2>Program untuk perjalanan Anda.</h2></div>${link('catalog','Lihat semua program '+icon('arrow'),'text-link')}</div><div class="module-grid">${state.products.filter(p=>has(p.id)).slice(0,3).map(productCard).join('')||empty('Mulai langkah pertama','Pilih program untuk mengaktifkan perjalanan belajar Anda.',link('catalog','Jelajahi program','btn primary'))}</div><div class="dashboard-bottom"><section><div class="section-heading compact"><h2>${icon('calendar','cyan-text')} Event terdekat</h2>${link('events','Semua jadwal','text-link')}</div>${next?eventCard(next):empty('Belum ada pendaftaran','Lihat jadwal workshop yang sesuai kebutuhan Anda.',link('events','Lihat jadwal','btn secondary'))}</section><section><div class="section-heading compact"><h2>${icon('shield','green-text')} Ruang perusahaan Anda</h2></div><div class="company-card"><span class="eyebrow">KNOWLEDGE BASE PRIVAT</span><h3>Kebijakan yang mudah<br>ditemukan kembali.</h3><p>Simpan PP, SOP, dan kebijakan perusahaan sebagai rujukan. ${state.documents.length} dokumen tersedia.</p>${link('policies','Kelola dokumen '+icon('arrow'),'btn secondary')}${link('knowledge','Buka pengetahuan '+icon('book'),'text-link')}</div></section></div>${companyKnowledge()}`}
function companyKnowledge(){const docs=state.documents.filter(d=>d.status==='berlaku'&&d.effective<=today()&&(!d.end||d.end>=today()));return `<section class="knowledge-section" aria-labelledby="knowledge-title"><div class="knowledge-intro"><span class="module-icon violet">${icon('book')}</span><span class="eyebrow lavender-text">RUJUKAN PRIVAT PERUSAHAAN</span><h2 id="knowledge-title">Pengetahuan Perusahaan</h2><p>Temukan kebijakan HR, Peraturan Perusahaan, dan SOP yang sesuai dengan perusahaan Anda. Baca langsung dokumen beserta versi dan tanggal berlakunya.</p><div class="knowledge-actions">${link('knowledge','Buka pengetahuan '+icon('arrow'),'btn primary')}${link('policies','Kelola dokumen '+icon('folder'),'btn secondary')}</div></div><div class="knowledge-topics"><div class="knowledge-status"><strong>${esc(user.company)}</strong>${badge(docs.length+' dokumen berlaku','green')}</div><p>Pilih kategori pengetahuan:</p>${['Peraturan Perusahaan (PP)','Kebijakan HR','SOP','Struktur Organisasi'].map(category=>button('knowledge-category',icon('folder')+esc(category)+icon('arrow'),'secondary',`data-id="${esc(category)}"`)).join('')}<small>Isi pengetahuan berasal dari dokumen yang disimpan pada akun perusahaan Anda.</small></div></section>`}
function catalog(){const items=state.products.filter(p=>(filter==='active'?has(p.id):filter==='locked'?!has(p.id):true)&&(!searchTerm||(p.title+' '+p.description+' '+p.tag).toLowerCase().includes(searchTerm.toLowerCase())));return `${title('EXPLORE YOUR NEXT SKILL','Kompetensi baru.<br>Peluang yang lebih luas.','Pilih program sesuai pekerjaan dan tujuan pengembangan Anda.')}<div class="filter-row"><div class="chips">${[['all','Semua program'],['active','Aktif'],['locked','Belum dibeli']].map(([id,t])=>button('catalog-filter',t,'chip '+(filter===id?'selected':''),`data-id="${id}"`)).join('')}</div><span class="muted">Harga ilustrasi · akses 12 bulan</span></div>${searchTerm?`<div class="callout">Hasil pencarian: “${esc(searchTerm)}” ${button('clear-search','Hapus pencarian','ghost')}</div>`:''}<div class="module-grid">${items.map(productCard).join('')||empty('Program belum ditemukan','Coba kata kunci lain.')}</div>`}
function productPage(id){const p=pub.products.find(p=>p.id===id);if(!p)return empty('Program tidak ditemukan','Kembali ke katalog.');return `<div class="product-detail container">${link(user?'catalog':'programs','← Kembali ke program','back-link')}<div class="product-hero"><div><span class="eyebrow cyan-text">${p.tag}</span><h1>${p.title}</h1><p>${p.description}</p><div class="feature-line">${icon('book')} ${p.lessons.length} materi praktik</div><div class="feature-line">${icon('calendar')} Akses selama 12 bulan</div><div class="feature-line">${icon('users')} Workshop terkait sesuai jadwal</div><h2>Yang akan Anda pelajari</h2>${p.lessons.map((l,i)=>`<div class="curriculum-row"><span>0${i+1}</span>${esc(l)}${icon('check')}</div>`).join('')}</div><aside class="purchase-card">${icon(p.icon)}${badge(p.level,'cyan')}<h3>Investasi kompetensi Anda</h3><div class="big-price">${money(p.price)}</div><p>per modul / 12 bulan · harga ilustrasi</p>${has(p.id)?link('learn/'+p.id,'Buka pembelajaran','btn primary full'):user?button('buy','Daftar program '+icon('arrow'),'primary full',`data-id="${p.id}"`):link('register','Buat akun untuk mendaftar','btn primary full')}<small>Pembayaran manual dan verifikasi admin. Membership tidak otomatis ditagihkan kembali.</small></aside></div></div>`}
function learningList(){return title('MY LEARNING','Ruang pembelajaran Anda.','Lanjutkan dari langkah terakhir, sesuai ritme Anda.')+`<div class="module-grid">${state.products.filter(p=>has(p.id)).map(productCard).join('')||empty('Belum ada modul aktif','Aktifkan program pertama Anda.',link('catalog','Lihat program','btn primary'))}</div>`}
function learnPage(id){if(!has(id))return empty('Akses belum aktif','Pilih dan aktifkan modul ini terlebih dahulu.',link('product/'+id,'Lihat program','btn primary'));if(!lesson)return '<div class="empty">Memuat materi…</div>';const done=state.progress.find(p=>p.module===id)?.done||[];return `${title('PEMBELAJARAN SAYA',esc(lesson.title),'Materi ilustrasi · pelajari konsep, lalu praktikkan.')}<div class="learning-layout"><aside class="lesson-sidebar"><span class="eyebrow">KURIKULUM PROGRAM</span>${lesson.lessons.map((l,i)=>button('lesson',`<span class="lesson-number">${done.includes(i)?icon('check'):i+1}</span><span>${esc(l)}</span>`,'lesson-link '+(activeLesson===i?'selected':''),`data-id="${i}"`)).join('')}${progressBar(Math.round(done.length/lesson.lessons.length*100))}<small>${done.length} dari ${lesson.lessons.length} materi selesai</small></aside><article class="lesson-content"><div class="lesson-visual"><div class="lesson-art">${icon(id==='jd'?'briefcase':'book')}</div><span class="eyebrow">MAXTON LEARNING NOTES</span><h2>${esc(lesson.lessons[activeLesson])}</h2></div><div class="lesson-body"><span class="eyebrow cyan-text">MATERI ${activeLesson+1} / ${lesson.lessons.length}</span><h2>${esc(lesson.lessons[activeLesson])}</h2><p class="prose">${esc(lesson.content[activeLesson])}</p><div class="callout">${icon('spark')} Catat satu hal yang bisa Anda terapkan di perusahaan minggu ini.</div><div class="lesson-actions">${button('complete',done.includes(activeLesson)?icon('check')+' Sudah selesai':'Tandai materi selesai '+icon('check'),'primary',`data-id="${id}"`)}${id==='jd'?link('workspace','Praktik di lembar kerja '+icon('arrow'),'btn secondary'):''}</div></div></article></div>`}
function eventsPage(){return `${title('LEARN TOGETHER','Jadwal & ruang diskusi.','Workshop dan sesi Zoom bersama praktisi. Seluruh jadwal dalam WIB.')}<div class="event-grid">${state.events.map(eventCard).join('')}</div>`}
const jobFields=j=>`${field('Nama jabatan','title',j?.title||'','','required')}${field('Departemen / Divisi','department',j?.department||'','','required')}${field('Atasan langsung','superior',j?.superior||'')}${field('Lokasi & format kerja','location',j?.location||'')}${textarea('Tujuan jabatan','purpose',j?.purpose||'','required rows="4"')}${textarea('Tanggung jawab — satu per baris','responsibilities',j?.responsibilities||'','required rows="6"')}${textarea('Wewenang','authority',j?.authority||'','rows="3"')}${textarea('Kualifikasi & kompetensi','qualifications',j?.qualifications||'','rows="3"')}`;
function jobPreview(j={}){j=j||{};return `<div class="document-paper"><div class="paper-header"><span class="eyebrow green-text">${esc(user.company)}</span>${badge('DRAFT','violet')}<h2>JOB DESCRIPTION</h2><p>Spesifikasi jabatan · ${esc(j.title||'Nama Jabatan')}</p></div><div class="paper-grid"><div><small>JABATAN</small><strong>${esc(j.title||'—')}</strong></div><div><small>DEPARTEMEN</small><strong>${esc(j.department||'—')}</strong></div><div><small>PELAPORAN</small><strong>${esc(j.superior||'—')}</strong></div><div><small>PENEMPATAN</small><strong>${esc(j.location||'—')}</strong></div></div><h4>01 / Tujuan Jabatan</h4><p class="prose">${esc(j.purpose||'Tujuan jabatan akan tampil di sini.')}</p><h4>02 / Tanggung Jawab Utama</h4><ol>${(j.responsibilities||'Tanggung jawab jabatan').split('\n').filter(Boolean).map(t=>`<li>${esc(t)}</li>`).join('')}</ol><h4>03 / Wewenang</h4><p class="prose">${esc(j.authority||'—')}</p><h4>04 / Kualifikasi & Kompetensi</h4><p class="prose">${esc(j.qualifications||'—')}</p><div class="paper-foot">Dokumen draft · Perlu ditinjau sesuai kebutuhan perusahaan.</div></div>`}
function workspace(){if(!has('jd'))return empty('Aktifkan modul Job Description','Lembar kerja tersedia untuk member dengan akses aktif.',link('product/jd','Lihat fasilitas','btn primary'));return `${title('MODUL KERJA / JOB DESCRIPTION','Studio Job Description.','Susun peran yang jelas. Bangun organisasi yang lebih terarah.',button('new-job',icon('plus')+' Draft baru','secondary'))}<div class="workspace-toolbar"><span>${icon('shield')} Dokumen privat · ${esc(user.company)}</span><div>${button('export-job',icon('download')+' Cetak / Simpan PDF','secondary')}${button('submit-job','Kirim review '+icon('arrow'),'primary')}</div></div><div class="editor-layout"><form class="editor-form panel" data-form="job"><div class="panel-heading"><h3>${icon('briefcase')} Informasi & tanggung jawab</h3>${badge(jobDraft?.id?'Draft tersimpan':'Draft baru','green')}</div><div class="form-grid">${jobFields(jobDraft)}</div><div class="form-error" role="alert"></div><button class="btn primary full" type="submit">Simpan draft ${icon('check')}</button><small id="save-status">Perubahan belum disimpan sampai Anda menekan Simpan draft.</small></form><aside class="preview-panel"><div class="preview-title"><h3>${icon('file','cyan-text')} Preview dokumen</h3>${badge('Live preview','cyan')}</div><div id="job-preview">${jobPreview(jobDraft)}</div></aside></div>`}
function documentsPage(){return `${title('MY DOCUMENTS','Hasil kerja Anda.','Semua draft Job Description tersimpan secara privat.',link('workspace',icon('plus')+' Buat dokumen','btn primary'))}${state.jobs.length?`<div class="table-wrap"><table><thead><tr><th>Dokumen</th><th>Departemen</th><th>Terakhir diubah</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${state.jobs.map(j=>`<tr><td><strong>${icon('file','lavender-text')} ${esc(j.title)}</strong><small>Job Description</small></td><td>${esc(j.department)}</td><td>${date(j.updated)}</td><td>${badge(j.status,'violet')}</td><td>${button('open-job','Buka '+icon('arrow'),'ghost',`data-id="${j.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada dokumen','Buka lembar kerja dan buat draft pertama.')}`}
function policies(){return `${title('COMPANY KNOWLEDGE BASE','Kebijakan, dalam satu ruang.','Sumber rujukan privat untuk '+esc(user.company)+'.',button('new-policy',icon('plus')+' Tambah dokumen','primary'))}<div class="policy-layout"><aside class="folder-nav panel"><span class="eyebrow">FOLDER PERUSAHAAN</span>${['Semua dokumen','Profil Perusahaan','Peraturan Perusahaan (PP)','Kebijakan HR','SOP','Struktur Organisasi','Remunerasi & Benefit','Arsip'].map(f=>button('folder',icon('folder')+f,'folder-link '+(filter===f||filter==='all'&&f==='Semua dokumen'?'selected':''),`data-id="${esc(f)}"`)).join('')}<div class="callout small">${icon('shield')} Dokumen tidak dibagikan otomatis ke akun lain.</div></aside><div><div class="policy-banner">${icon('book')} Simpan kebijakan dan SOP, lalu baca dokumen berlaku di Pengetahuan Perusahaan. ${link('ai','Tanya kebijakan '+icon('arrow'),'text-link')}</div><div class="document-grid">${state.documents.filter(d=>filter==='all'||filter==='Semua dokumen'||filter==='Arsip'&&d.status==='arsip'||d.category===filter).map(d=>`<article class="policy-card panel"><div class="card-top"><span class="module-icon violet">${icon('file')}</span>${badge(d.status,d.status==='berlaku'?'green':'muted')}</div><h3>${esc(d.title)}</h3><p>${esc(d.category)}</p><dl><div><dt>Versi</dt><dd>${esc(d.version)}</dd></div><div><dt>Berlaku sejak</dt><dd>${date(d.effective)}</dd></div><div><dt>Cakupan</dt><dd>${esc(d.scope||'Belum diisi')}</dd></div></dl><span class="ready-line">${icon('check')} Teks tersedia untuk dirujuk</span>${button('edit-policy','Buka dokumen '+icon('arrow'),'secondary full',`data-id="${d.id}"`)}</article>`).join('')||empty('Folder masih kosong','Tambahkan PP, SOP, atau kebijakan perusahaan Anda.')}</div></div></div>`}
let knowledgeCategory='all';
function knowledgePage(){const allDocs=state.documents.filter(d=>d.status==='berlaku'&&d.effective<=today()&&(!d.end||d.end>=today()));const docs=allDocs.filter(d=>knowledgeCategory==='all'||d.category===knowledgeCategory);return `${title('COMPANY KNOWLEDGE','Pengetahuan Perusahaan.','Kebijakan dan panduan kerja untuk '+esc(user.company)+'.',link('policies',icon('folder')+' Kelola dokumen','btn secondary'))}<div class="callout">${icon('shield')} Baca langsung sumber kebijakan perusahaan. Hanya dokumen berstatus berlaku dan sesuai masa efektif yang ditampilkan.</div><div class="chips">${[['all','Semua'],...['Peraturan Perusahaan (PP)','Kebijakan HR','SOP','Profil Perusahaan','Struktur Organisasi','Remunerasi & Benefit'].map(c=>[c,c])].map(([id,label])=>button('knowledge-category',label,'chip '+(knowledgeCategory===id?'selected':''),`data-id="${esc(id)}"`)).join('')}</div><div class="document-grid">${docs.map(d=>`<article class="panel knowledge-document"><div class="card-top"><span class="module-icon violet">${icon('file')}</span>${badge('Berlaku','green')}</div><span class="eyebrow">${esc(d.category)}</span><h3>${esc(d.title)}</h3><p>${esc(d.text.slice(0,200))}${d.text.length>200?'…':''}</p><div class="knowledge-document-meta"><span>Versi ${esc(d.version)}</span><span>Berlaku ${date(d.effective)}</span></div>${button('view-source','Baca kebijakan '+icon('arrow'),'secondary full',`data-id="${d.id}"`)}</article>`).join('')||empty('Belum ada pengetahuan pada kategori ini','Tambahkan kebijakan atau SOP dan tetapkan status berlaku.',link('policies','Kelola dokumen','btn primary'))}</div>`}
function billing(){return `${title('MEMBERSHIP & BILLING','Investasi perjalanan Anda.','Kelola masa akses, pembelian, dan perpanjangan modul.')}<div class="callout">${icon('wallet')} Mode uji lokal: harga dan transaksi adalah ilustrasi. Jangan melakukan transfer uang nyata.</div><h2 class="section-title">Modul & masa akses</h2><div class="access-grid">${state.products.filter(p=>state.access.some(a=>a.module===p.id)).map(p=>{const a=state.access.filter(a=>a.module===p.id).sort((a,b)=>b.end.localeCompare(a.end))[0];return `<article class="panel access-card"><span class="module-icon ${p.color}">${icon(p.icon)}</span><h3>${p.title}</h3>${badge(has(p.id)?'Aktif':'Berakhir',has(p.id)?'green':'amber')}<p>Aktif sampai <strong>${date(a.end)}</strong></p>${button('buy','Perpanjang 12 bulan','secondary',`data-id="${p.id}"`)}</article>`}).join('')||empty('Belum ada akses','Beli modul untuk memulai.',link('catalog','Pilih program','btn primary'))}</div><h2 class="section-title">Pesanan & pembayaran</h2>${state.orders.length?`<div class="table-wrap"><table><thead><tr><th>Invoice / program</th><th>Tanggal</th><th>Nilai</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>${state.orders.map(o=>`<tr><td><strong>${esc(o.title)}</strong><small>INV-${o.id.slice(0,8).toUpperCase()}</small></td><td>${date(o.created)}</td><td>${money(o.amount)}</td><td>${badge(o.status,o.status==='Dibayar'?'green':'amber')}</td><td>${o.status==='Menunggu pembayaran'?button('payment','Konfirmasi transfer','secondary',`data-id="${o.id}"`):o.status==='Dibayar'?icon('check','green-text'):'Menunggu admin'}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada transaksi','Pembelian dan perpanjangan akan tampil di sini.')}`}
function feedback(){return `${title('PRACTICE & FEEDBACK','Belajar dari setiap perbaikan.','Kirim draft melalui Studio Job Description untuk mendapat review.')}<div class="feedback-list">${state.submissions.map(s=>`<article class="panel feedback-card"><div>${badge(s.status,s.feedback?'green':'amber')}<h3>${esc(s.title)}</h3><small>Dikirim ${date(s.created)}</small></div><p class="prose">${esc(s.feedback||'Praktisi belum memberikan feedback. Pantau status di halaman ini.')}</p>${button('open-job','Buka draft untuk revisi','secondary',`data-id="${s.jobId}"`)}</article>`).join('')||empty('Belum ada tugas dikirim','Simpan draft lalu pilih Kirim review di lembar kerja.',link('workspace','Buka lembar kerja','btn primary'))}</div>`}
function profile(){return `${title('PROFILE & SUPPORT','Kebutuhan Anda, titik awal kami.','Perbarui profil dan hubungi tim Maxton.')}<div class="two-columns"><form class="panel" data-form="profile"><h3>Profil pembelajaran</h3>${field('Nama','name',user.name,'text','required')}${field('Jabatan','position',user.position||'')}${field('Skill yang ingin dikembangkan (pisahkan koma)','skills',(user.skills||[]).join(', '))}<div class="readonly">${icon('briefcase')} ${esc(user.company)}<small>Perubahan perusahaan perlu bantuan admin.</small></div><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Simpan profil</button></form><div><form class="panel" data-form="ticket"><h3>Hubungi tim Maxton</h3>${field('Subjek','subject','','text','required')}${textarea('Ceritakan kebutuhan Anda','message','','required rows="4"')}<div class="form-error" role="alert"></div><button class="btn secondary" type="submit">Kirim permintaan</button></form>${state.tickets.map(t=>`<div class="panel ticket"><strong>${esc(t.subject)}</strong>${badge(t.status,'cyan')}<p>${esc(t.message)}</p>${t.reply?`<div class="callout">${esc(t.reply)}</div>`:''}</div>`).join('')}</div></div>`}
function adminPage(page){if(page==='knowledge')return knowledgePage();if(page==='policies')return policies();const name=id=>admin.users.find(u=>u.id===id)?.name||id;const pending=admin.orders.filter(o=>o.status==='Menunggu verifikasi');if(page==='admin')return `${title('MAXTON OPERATIONS','Gambaran bisnis hari ini.','Pantau layanan, member, dan pekerjaan tim dalam satu ruang.',badge('Admin workspace','violet'))}<div class="metric-grid">${[[admin.users.filter(u=>u.role==='member').length,'Member terdaftar','users'],[money(admin.orders.filter(o=>o.status==='Dibayar').reduce((n,o)=>n+o.amount,0)),'Pembayaran terverifikasi','wallet'],[pending.length,'Menunggu verifikasi','clock'],[admin.submissions.filter(s=>!s.feedback).length,'Tugas perlu review','file']].map(([n,t,i])=>`<div class="metric"><div>${t}<span class="module-icon violet">${icon(i)}</span></div><strong class="${String(n).length>8?'small-value':''}">${n}</strong><p>Data ilustrasi · lokal</p></div>`).join('')}</div><div class="dashboard-bottom"><div><h2>Perlu perhatian</h2>${pending.length?pending.map(o=>`<div class="panel attention"><div><h3>${esc(o.title)}</h3><p>${esc(name(o.userId))} · ${money(o.amount)}</p></div>${link('payments','Tinjau '+icon('arrow'),'btn primary')}</div>`).join(''):empty('Antrean pembayaran kosong','Pesanan baru akan muncul setelah member melakukan konfirmasi.')}</div><div><h2>Tugas tim</h2>${admin.tasks.slice(0,3).map(t=>`<div class="panel task-mini"><strong>${esc(t.title)}</strong><p>${esc(t.owner)} · ${date(t.date)}</p>${badge(t.status,t.status==='Selesai'?'green':'amber')}</div>`).join('')}${link('team','Kelola tugas '+icon('arrow'),'text-link')}</div></div><h2 class="section-title">Jejak aktivitas</h2><div class="panel">${admin.audit.slice(0,8).map(a=>`<div class="audit-row"><span>${esc(a.action)}</span><small>${date(a.at)} · ${esc(name(a.actor))}</small></div>`).join('')||'<p>Belum ada tindakan admin.</p>'}</div>`;
if(page==='members')return title('MEMBERS & ACCESS','Member dan hak akses.','Akses per modul berlaku 12 bulan sejak aktivasi.')+`<div class="table-wrap"><table><thead><tr><th>Member</th><th>Perusahaan</th><th>Modul aktif</th><th>Tanggal akhir terdekat</th></tr></thead><tbody>${admin.users.filter(u=>u.role==='member').map(u=>{const a=admin.access.filter(a=>a.userId===u.id&&new Date(a.end)>new Date());return `<tr><td><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></td><td>${esc(u.company)}</td><td>${a.map(x=>badge(state.products.find(p=>p.id===x.module)?.title||x.module,'violet')).join(' ')||'Belum ada akses'}</td><td>${a.length?date(a.map(x=>x.end).sort()[0]):'—'}</td></tr>`}).join('')}</tbody></table></div>`;
if(page==='payments')return title('PAYMENT OPERATIONS','Pesanan & verifikasi.','Konfirmasi pembayaran mengaktifkan atau memperpanjang akses 12 bulan.')+`<div class="callout">${icon('shield')} Semua transaksi saat ini adalah simulasi lokal. Tidak ada pembayaran bank yang diproses.</div>`+(admin.orders.length?`<div class="table-wrap"><table><thead><tr><th>Member / program</th><th>Nilai</th><th>Referensi</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${admin.orders.map(o=>`<tr><td><strong>${esc(name(o.userId))}</strong><small>${esc(o.title)}</small></td><td>${money(o.amount)}</td><td>${esc(o.reference||'—')}<small>${esc(o.note)}</small></td><td>${badge(o.status,o.status==='Dibayar'?'green':'amber')}</td><td>${o.status==='Menunggu verifikasi'?button('approve','Verifikasi & aktifkan','primary',`data-id="${o.id}"`):'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada pesanan','Transaksi dari member akan tampil di sini.'));
if(page==='manage-events')return title('EVENT OPERATIONS','Pertemuan Exclusive & Workshop','Buat jadwal, tentukan modul, dan kelola peserta.',button('new-event',icon('plus')+' Buat event','primary'))+`<div class="event-grid">${admin.events.map(e=>`<article class="panel"><span class="eyebrow cyan-text">${date(e.date)} · ${time(e.date)}</span><h3>${esc(e.title)}</h3><p>${esc(e.mentor)}</p><p>${admin.registrations.filter(r=>r.eventId===e.id).length} / ${e.capacity} peserta</p>${badge(e.link?'Link tersedia':'Link belum disiapkan',e.link?'green':'amber')}<div class="participant-list">${admin.registrations.filter(r=>r.eventId===e.id).map(r=>`<small>${esc(name(r.userId))}</small>`).join('')}</div></article>`).join('')}</div>`;
if(page==='reviews')return title('LEARNER SUPPORT','Review & dukungan member.','Berikan feedback yang konkret dan dapat diterapkan.')+`<h2>Dokumen menunggu review</h2>${admin.submissions.map(s=>`<article class="panel review-item"><div>${badge(s.status,s.feedback?'green':'amber')}<h3>${esc(s.title)}</h3><p>${esc(name(s.userId))} · ${date(s.created)}</p></div><details><summary>Lihat dokumen yang dikirim</summary><p class="prose">${esc(s.snapshot?.purpose||'')}</p><p class="prose">${esc(s.snapshot?.responsibilities||'')}</p></details><form data-form="review" data-id="${s.id}">${textarea('Feedback praktisi','feedback',s.feedback,'required rows="3"')}<button class="btn primary" type="submit">Kirim feedback</button><div class="form-error" role="alert"></div></form></article>`).join('')||empty('Belum ada tugas','Kiriman peserta akan tampil di sini.')}<h2 class="section-title">Permintaan bantuan</h2>${admin.tickets.map(t=>`<article class="panel review-item"><h3>${esc(t.subject)}</h3><small>${esc(name(t.userId))}</small><p>${esc(t.message)}</p><form data-form="reply" data-id="${t.id}">${textarea('Balasan','reply',t.reply,'required')}<button class="btn secondary" type="submit">Balas</button><div class="form-error" role="alert"></div></form></article>`).join('')||'<p class="muted">Belum ada permintaan.</p>'}`;
if(page==='team')return title('TEAM WORKSPACE','Tiga peran. Satu tujuan.','Kelola pekerjaan program, marketing, dan operasional.',button('new-task',icon('plus')+' Tambah tugas','primary'))+`<div class="kanban">${['Belum dimulai','Dikerjakan','Selesai'].map(status=>`<section><h3>${status} <span>${admin.tasks.filter(t=>t.status===status).length}</span></h3>${admin.tasks.filter(t=>t.status===status).map(t=>`<article class="panel task-card"><h3>${esc(t.title)}</h3><p>${esc(t.owner)} · ${date(t.date)}</p>${button('edit-task','Perbarui status '+icon('arrow'),'secondary full',`data-id="${t.id}"`)}</article>`).join('')}</section>`).join('')}</div>`;
return title('SYSTEM STATUS','Konfigurasi lokal.','Kunci API disimpan pada server, tidak dikirim ke browser.')+`<div class="panel settings-card"><h3>${icon('spark')} AI kebijakan perusahaan</h3>${badge(admin.aiConfigured?'API terkonfigurasi':'Belum dikonfigurasi',admin.aiConfigured?'green':'amber')}<p>Salin .env.example menjadi .env, isi OPENAI_API_KEY dan OPENAI_MODEL, lalu mulai ulang aplikasi. Gunakan model yang tersedia pada akun API Anda.</p><h3>Penyimpanan & akun</h3><p>SQLite lokal: data/maxton.sqlite. Sesi login berlaku 24 jam dan berakhir jika server dimulai ulang. Aplikasi hanya mendengarkan koneksi localhost.</p><h3>Batas versi awal</h3><p>Materi berbentuk teks contoh. Dokumen sumber dapat dimasukkan sebagai teks atau file .txt/.md; PDF dan Word belum diekstrak otomatis. Email, payment gateway, dan akun perusahaan bersama belum diaktifkan.</p></div>`}
async function render(){try{const page=route();if(page==='login'||page==='register'){$('#app').innerHTML=authPage(page==='register');return}if(page.startsWith('product/')){$('#app').innerHTML=user?shell(productPage(page.split('/')[1])):`<header class="public-header"><div class="container public-nav">${logo()}${link('home','Kembali ke website','btn secondary')}</div></header>`+productPage(page.split('/')[1]);return}if(['home','programs','agenda'].includes(page)){$('#app').innerHTML=publicPage();if(page!=='home')requestAnimationFrame(()=>$(page==='programs'?'#program-section':'#event-section')?.scrollIntoView());return}if(!user){location.hash='login';return}if(!state)await refresh();let content;if(user.role==='admin'){content=adminPage(adminNav.some(n=>n[0]===page)?page:'admin')}else if(page.startsWith('learn/')){const id=page.split('/')[1];lesson=await api('lesson?module='+encodeURIComponent(id));activeLesson=Math.min(activeLesson,lesson.lessons.length-1);content=learnPage(id)}else content=({dashboard,catalog,learning:learningList,workspace,events:eventsPage,documents:documentsPage,policies,ai:knowledgePage,knowledge:knowledgePage,billing,feedback,profile}[page]||dashboard)();$('#app').innerHTML=shell(content);}catch(e){toast(e.message);$('#app').innerHTML=user?shell(empty('Halaman belum dapat dibuka',e.message,link('dashboard','Kembali ke beranda','btn primary'))):authPage()}}
function modal(title,content){const old=$('#modal');if(old)old.remove();const el=document.createElement('dialog');el.id='modal';el.innerHTML=`<div class="modal-heading"><h2>${title}</h2>${button('close-modal',icon('close'),'icon-button','aria-label="Tutup dialog"')}</div>${content}`;document.body.append(el);el.showModal();el.addEventListener('click',e=>{if(e.target===el)el.close()});el.addEventListener('close',()=>el.remove());}
function policyForm(d){docEdit=d;modal(d?'Perbarui dokumen':'Tambah dokumen perusahaan',`<form data-form="policy">${field('Judul dokumen','title',d?.title||'','text','required')}${select('Folder','category',['Profil Perusahaan','Peraturan Perusahaan (PP)','Kebijakan HR','SOP','Struktur Organisasi','Remunerasi & Benefit'].map(v=>[v,v]),d?.category)}<div class="form-grid">${field('Versi','version',d?.version||'1.0','text','required')}${select('Status','status',['draft','berlaku','arsip','dicabut'].map(v=>[v,v]),d?.status||'draft')}${field('Berlaku sejak','effective',d?.effective||today(),'date','required')}${field('Berakhir pada (opsional)','end',d?.end||'','date')}</div>${field('Cakupan unit / jabatan','scope',d?.scope||'')}${field('Impor file teks (.txt / .md)','sourceFile','','file','accept=".txt,.md" id="policy-file"')}${textarea('Isi dokumen / pasal kebijakan','text',d?.text||'','required rows="9" maxlength="60000"')}<small>PDF/Word belum didukung otomatis. Salin teks dokumen dan periksa isinya sebelum menetapkan berlaku.</small><div class="form-error" role="alert"></div><div class="modal-actions">${d?button('delete-policy','Hapus dokumen','danger',`data-id="${d.id}"`):''}<button class="btn primary" type="submit">Simpan dokumen</button></div></form>`)}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;e.preventDefault();const action=target.dataset.action,id=target.dataset.id;try{
if(action==='chat-toggle'||action==='chat-close'){chatOpen=action==='chat-close'?false:!chatOpen;paintChat(chatOpen);if(!chatOpen)$('#chat-widget .chat-widget-launcher')?.focus();return}
if(action==='chat-example'){chatDraft='Bagaimana prosedur pengajuan pelatihan?';paintChat(true);return}
if(action==='close-modal'){$('#modal').close();return}if(action==='about'){modal('Tentang Maxton','<p>MAXTON HUMAN CAPITAL LEARNING CENTRE adalah ruang pembelajaran Human Capital berbasis praktik untuk PIC HRD, supervisor, dan HR manager.</p><p>Belajar melalui materi, workshop, serta penerapan dalam dokumen kerja.</p>');return}
if(action==='knowledge-category'){knowledgeCategory=id;if(route()==='knowledge')await render();else location.hash='knowledge';return}
if(action==='clear-search'){searchTerm='';await render();return}
if(action==='menu'){$('.sidebar').classList.toggle('open');return}if(action==='logout'){await api('logout',{});user=null;state=null;admin=null;location.hash='home';await render();return}
if(action.startsWith('demo-')){$('[name=email]').value=action==='demo-admin'?'admin@maxton.local':'member@maxton.local';$('[name=password]').value=action==='demo-admin'?'MaxtonAdmin!2026':'MaxtonMember!2026';return}
if(action==='public-filter'||action==='catalog-filter'||action==='folder'){filter=id;await render();return}
if(action==='buy'){target.disabled=true;await api('orders',{module:id});await refresh();location.hash='billing';toast('Pesanan dibuat. Lanjutkan konfirmasi pembayaran simulasi.');return}
if(action==='payment'){modal('Konfirmasi pembayaran simulasi',`<p>Untuk uji coba alur, isi referensi contoh. Jangan transfer uang nyata.</p><form data-form="payment" data-id="${id}">${field('Referensi transfer / nomor bukti','reference','','text','required')}${textarea('Catatan','note')}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">Kirim konfirmasi</button></form>`);return}
if(action==='event-register'){await api('event-register',{eventId:id});await refresh();await render();toast('Pendaftaran event berhasil.');return}
if(action==='event-detail'){const ev=state.events.find(x=>x.id===id);modal(esc(ev.title),`<p>${date(ev.date)} · ${time(ev.date)}</p><p>${esc(ev.mentor)}</p>${ev.link?`<a class="btn primary" href="${esc(ev.link)}" target="_blank" rel="noopener">Buka sesi Zoom</a>`:'<div class="callout">Link sesi belum disiapkan admin. Jadwal ini adalah ilustrasi.</div>'}<div class="modal-actions">${button('event-cancel','Batalkan pendaftaran','secondary',`data-id="${id}"`)}</div>`);return}
if(action==='event-cancel'){await api('event-cancel',{eventId:id});$('#modal').close();await refresh();await render();toast('Pendaftaran dibatalkan.');return}
if(action==='lesson'){activeLesson=Number(id);await render();return}if(action==='complete'){await api('progress',{module:id,lesson:activeLesson});await refresh();await render();toast('Progres tersimpan.');return}
if(action==='new-job'){jobDraft=null;await render();return}if(action==='open-job'){jobDraft=state.jobs.find(j=>j.id===id);location.hash='workspace';await render();return}
if(action==='export-job'){const form=$('[data-form=job]');const j=form?Object.fromEntries(new FormData(form)):jobDraft;const w=window.open('','_blank');if(!w){toast('Izinkan pop-up untuk mencetak dokumen.');return}w.document.write(`<!doctype html><html lang="id"><head><title>Job Description — ${esc(j?.title||'Draft')}</title><style>body{font:14px/1.6 Arial,sans-serif;color:#18202b;margin:40px}h2{font-size:25px}.paper-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;border-block:1px solid #ddd;padding:16px 0}.paper-grid strong,.paper-grid small{display:block}.badge{float:right}h4{margin-top:30px}.eyebrow{font-size:12px}.paper-foot{margin-top:40px;font-size:11px}.prose{white-space:pre-wrap}@page{size:A4;margin:18mm}@media print{body{margin:0}}</style></head><body>${jobPreview(j)}</body></html>`);w.document.close();w.print();return}
if(action==='submit-job'){if(!jobDraft?.id){toast('Simpan draft terlebih dahulu sebelum mengirim review.');return}await api('submissions',{jobId:jobDraft.id});await refresh();toast('Draft tersimpan dikirim untuk review.');location.hash='feedback';return}
if(action==='new-policy'){policyForm(null);return}if(action==='edit-policy'){policyForm(state.documents.find(d=>d.id===id));return}if(action==='delete-policy'){if(!confirm('Hapus dokumen ini? Dokumen tidak dapat digunakan lagi sebagai sumber AI.'))return;await api('document-delete',{id});$('#modal').close();await refresh();await render();toast('Dokumen dihapus.');return}
if(action==='view-source'){const d=state.documents.find(d=>d.id===id);if(!d){toast('Sumber sudah dihapus atau tidak tersedia.');return}modal(esc(d.title),`${badge(d.status,d.status==='berlaku'?'green':'amber')}<p>Versi ${esc(d.version)} · berlaku ${date(d.effective)}</p><p class="prose source-text">${esc(d.text)}</p>`);return}
if(action==='approve'){target.disabled=true;await api('admin/approve',{id});await refresh();await render();toast('Pembayaran diverifikasi. Akses aktif selama 12 bulan.');return}
if(action==='new-task'||action==='edit-task'){const t=admin.tasks.find(t=>t.id===id);modal(t?'Perbarui tugas':'Tambah tugas tim',`<form data-form="task" data-id="${t?.id||''}">${field('Tugas','title',t?.title||'','text','required')}${select('PIC','owner',['Program','Marketing & Sales','Operasional'].map(v=>[v,v]),t?.owner)}${field('Tenggat','date',t?.date||today(),'date','required')}${select('Status','status',['Belum dimulai','Dikerjakan','Selesai'].map(v=>[v,v]),t?.status)}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">Simpan tugas</button></form>`);return}
if(action==='new-event'){modal('Buat event',`<form data-form="event">${field('Judul','title','','text','required')}${select('Modul terkait','module',state.products.map(p=>[p.id,p.title]))}${field('Tanggal & jam (zona waktu komputer)','date','','datetime-local','required')}${field('Kuota','capacity','25','number','required min="1" max="1000"')}${field('Praktisi','mentor','','text','required')}${field('Link Zoom (opsional)','link','','url')}${textarea('Deskripsi','description')}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">Buat event</button></form>`);return}
}catch(err){target.disabled=false;toast(err.message)}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const kind=form.dataset.form;const data=Object.fromEntries(new FormData(form));const submit=form.querySelector('[type=submit]');const error=form.querySelector('.form-error')||(kind==='ai'?$('#ai-error'):null);if(error)error.textContent='';if(submit)submit.disabled=true;try{
if(kind==='chat-widget'){await sendChat(data.question.trim());return}
if(kind==='login'||kind==='register'){user=await api(kind,data);await refresh();location.hash=user.role==='admin'?'admin':'dashboard';return}
if(kind==='job'){jobDraft=await api('jobs',{...data,id:jobDraft?.id});await refresh();$('#save-status').textContent='Draft tersimpan · '+time(new Date());toast('Draft berhasil disimpan.');await render();return}
if(kind==='policy'){await api('documents',{...data,id:docEdit?.id});$('#modal').close();await refresh();await render();toast('Dokumen perusahaan tersimpan.');return}
if(kind==='payment'){await api('payment',{...data,id:form.dataset.id});$('#modal').close();await refresh();await render();toast('Konfirmasi dikirim. Menunggu verifikasi admin.');return}
if(kind==='profile'){await api('profile',{...data,skills:data.skills.split(',').map(s=>s.trim()).filter(Boolean)});await refresh();toast('Profil tersimpan.');return}
if(kind==='ticket'){await api('tickets',data);await refresh();await render();toast('Permintaan terkirim.');return}
if(['review','reply','task','event'].includes(kind)){await api('admin/'+kind,{...data,id:form.dataset.id});$('#modal')?.close();await refresh();await render();toast('Perubahan tersimpan.');return}
}catch(err){if(error)error.textContent=err.message;else toast(err.message)}finally{if(submit){submit.disabled=false;if(kind==='ai')submit.innerHTML=icon('arrow')}}});
document.addEventListener('input',e=>{if(e.target.id==='chat-widget-question')chatDraft=e.target.value;const form=e.target.closest('[data-form=job]');if(form){const data=Object.fromEntries(new FormData(form));$('#job-preview').innerHTML=jobPreview(data);$('#save-status').textContent='Ada perubahan yang belum disimpan.'}});
document.addEventListener('change',async e=>{if(e.target.id==='policy-file'){const f=e.target.files[0];if(!f)return;if(f.size>60000){toast('File maksimal 60 KB.');return}if(!/\.(txt|md)$/i.test(f.name)){toast('Pilih file .txt atau .md.');return}$('#modal [name=text]').value=await f.text();if(!$('#modal [name=title]').value)$('#modal [name=title]').value=f.name.replace(/\.[^.]+$/,'')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&chatOpen&&!$('#modal')){chatOpen=false;paintChat();$('#chat-widget .chat-widget-launcher')?.focus()}if(e.key==='Enter'&&e.target.id==='global-search'){searchTerm=e.target.value.trim();filter='all';if(route()==='catalog')render();else location.hash='catalog'}});
window.addEventListener('hashchange',()=>{filter='all';window.scrollTo(0,0);render()});
async function init(){pub=await api('public');try{user=await api('me');await refresh()}catch{}await render()}
init().catch(e=>{$('#app').innerHTML=empty('Server belum dapat dihubungi',e.message)});
